-- Table: hrm_attendance_detail
-- Source: accounting_admin_db.sql (7. HRMIS)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS hrm_attendance_detail (
    id                   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    attendance_period_id BIGINT NOT NULL REFERENCES hrm_attendance_period(id) ON DELETE CASCADE,
    employee_id          BIGINT NOT NULL REFERENCES masterdata_employee(id),
    work_date            DATE NOT NULL,
    check_in_time        TIME,
    check_out_time       TIME,
    status               VARCHAR(20) NOT NULL DEFAULT 'present'
                         CHECK (status IN ('present', 'absent', 'leave', 'holiday', 'sick')),
    overtime_hours       NUMERIC(9,2) NOT NULL DEFAULT 0 CHECK (overtime_hours >= 0),
    notes                TEXT,
    UNIQUE (attendance_period_id, employee_id, work_date)
);
